#include <iostream>

// Abbruchbedingung: bei 1 hoert die Rekursion auf.
unsigned long long fakultaet(unsigned int n) {
    if (n <= 1) {
        return 1;                  // Abbruch, kein weiterer Aufruf
    }
    return n * fakultaet(n - 1);   // Rekursionsschritt
}

int main() {
    std::cout << "5! = " << fakultaet(5) << "\n";
    std::cout << "0! = " << fakultaet(0) << "\n";

    // Ohne Abbruchbedingung ruft sich die Funktion endlos auf.
    // Das Programm stuerzt dann mit einem Stack-Overflow ab.
    return 0;
}

#include <iostream>

// Jeder Aufruf belegt einen neuen Rahmen auf dem Stack.
int tiefe(int n) {
    std::cout << "Aufruf Nummer " << n << "\n";
    if (n >= 4) {
        return n;              // Abbruch, tief genug
    }
    return tiefe(n + 1);
}

int main() {
    int letzter = tiefe(1);
    std::cout << "tiefster Aufruf: " << letzter << "\n";

    // Dieselbe Arbeit mit einer Schleife: kein neuer Stack-Rahmen.
    for (int i = 1; i <= 4; ++i) {
        std::cout << "Schleife " << i << "\n";
    }
    return 0;
}

#include <iostream>

unsigned long long fakultaet_rekursiv(unsigned int n) {
    if (n <= 1) {
        return 1;
    }
    return n * fakultaet_rekursiv(n - 1);
}

unsigned long long fakultaet_schleife(unsigned int n) {
    unsigned long long ergebnis = 1;
    for (unsigned int i = 2; i <= n; ++i) {
        ergebnis *= i;
    }
    return ergebnis;
}

unsigned long long fibonacci_rekursiv(unsigned int n) {
    if (n < 2) {
        return n;
    }
    return fibonacci_rekursiv(n - 1) + fibonacci_rekursiv(n - 2);
}

unsigned long long fibonacci_schleife(unsigned int n) {
    unsigned long long a = 0;
    unsigned long long b = 1;
    for (unsigned int i = 0; i < n; ++i) {
        unsigned long long neu = a + b;
        a = b;
        b = neu;
    }
    return a;
}

int main() {
    std::cout << "5! rekursiv: " << fakultaet_rekursiv(5) << "\n";
    std::cout << "5! Schleife: " << fakultaet_schleife(5) << "\n";
    std::cout << "fib(10) rekursiv: " << fibonacci_rekursiv(10) << "\n";
    std::cout << "fib(10) Schleife: " << fibonacci_schleife(10) << "\n";
    return 0;
}

#include <iostream>
#include <vector>

// Sortiert den Bereich von links bis rechts mit Merge sort.
void merge_sort(std::vector<int>& werte, std::size_t links, std::size_t rechts) {
    if (rechts - links < 2) {
        return;                        // null oder ein Wert ist schon sortiert
    }

    std::size_t mitte = links + (rechts - links) / 2;
    merge_sort(werte, links, mitte);   // erste Haelfte sortieren
    merge_sort(werte, mitte, rechts);  // zweite Haelfte sortieren

    std::vector<int> gemischt;
    std::size_t i = links;
    std::size_t j = mitte;
    while (i < mitte && j < rechts) {
        if (werte[i] <= werte[j]) {
            gemischt.push_back(werte[i]);
            ++i;
        } else {
            gemischt.push_back(werte[j]);
            ++j;
        }
    }
    while (i < mitte) {
        gemischt.push_back(werte[i]);
        ++i;
    }
    while (j < rechts) {
        gemischt.push_back(werte[j]);
        ++j;
    }

    for (std::size_t k = 0; k < gemischt.size(); ++k) {
        werte[links + k] = gemischt[k];
    }
}

int main() {
    std::vector<int> zahlen = {5, 2, 9, 1, 7, 3};
    merge_sort(zahlen, 0, zahlen.size());
    for (int z : zahlen) {
        std::cout << z << " ";
    }
    std::cout << "\n";
    return 0;
}

