#include <iostream>

bool ist_primzahl(int n) {
    if (n < 2) {
        return false;
    }
    for (int teiler = 2; teiler * teiler <= n; ++teiler) {
        if (n % teiler == 0) {
            return false;   // früh abbrechen
        }
    }
    return true;
}

int main() {
    for (int n = 1; n <= 20; ++n) {
        if (ist_primzahl(n)) {
            std::cout << n << " ";
        }
    }
    std::cout << "\n";
    return 0;
}

#include <iostream>
#include <vector>

double durchschnitt(const std::vector<int>& noten) {
    if (noten.empty()) {
        return 0.0;
    }
    int summe = 0;
    for (std::size_t i = 0; i < noten.size(); ++i) {
        summe += noten[i];
    }
    return static_cast<double>(summe) / static_cast<double>(noten.size());
}

int main() {
    std::vector<int> noten = {2, 3, 1, 4};
    std::cout << durchschnitt(noten) << "\n";
    std::cout << durchschnitt({}) << "\n";
    return 0;
}
